using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.Networking;
using CatCafePreview.Standalone;
namespace CatCafePreview {
 public sealed class StandaloneEquipmentConversationSmoke:MonoBehaviour {
  static int checks;static void Check(bool ok,string label){checks++;if(!ok)throw new Exception("Equipment ADV: "+label);}
  static CafeResponse Send(LocalCafeBackend b,string kind,string choice=null,int slot=1,string id=null){var s=b.Simulation.State;CafeResponse r=null;var call=b.Request("/commands",JsonUtility.ToJson(new PythonShiftCommand{request_id=Guid.NewGuid().ToString("N"),instance_id=s.instance_id,expected_revision=s.revision,kind=kind,choice=choice,event_id=id??CafeEquipmentDialogue.EventId(s.day),save_slot=slot,save_id=slot.ToString(),working_cats=new string[0]}),v=>r=v);while(call.MoveNext()){}return r;}
  static void Good(LocalCafeBackend b,string kind,string choice=null,int slot=1){var r=Send(b,kind,choice,slot);Check(r.result==UnityWebRequest.Result.Success,kind+": "+r.error);}
  public static CafeRules Rules(){var r=JsonUtility.FromJson<CafeRules>(Resources.Load<TextAsset>("CatCafeStandalone/rules").text);r.intake.day=r.regular_introduction.day=9999;r.growth.threshold=10000;return r;}
  static int Seed(CafeRules r,bool consecutive=false){for(int i=0;i<10000;i++){var s=new CafeSimulation(r,i,"free");if(s.CurrentStoreEvent.type=="trouble" && (!consecutive || CafeSimulation.StoreDraw(i,2,"occur")<r.store_events.probability && (int)(CafeSimulation.StoreDraw(i,2,"type")*5)==3))return i;}throw new Exception("seed absent");}
  public static void Setup(LocalCafeBackend b,bool consecutive=false){b.Simulation.Restore(new CafeSimulation(b.Simulation.Rules,Seed(b.Simulation.Rules,consecutive),"free").State);b.PrepareEquipmentConversation();}
  static string Facts(LocalCafeBackend b){var s=JsonUtility.FromJson<CafeSnapshot>(JsonUtility.ToJson(b.Simulation.State));s.revision=0;s.NormalizeJsonStrings();return JsonUtility.ToJson(s);}
  static void Finish(LocalCafeBackend b){foreach(var r in b.EquipmentConversations.Where(x=>x.progress.branch_id!="introduction")){r.progress.node=3;r.progress.page_offset=0;CafeEquipmentDialogue.Finish(r);}b.RememberViewedConversations();}
  static void Legacy(LocalCafeBackend b,string folder,bool waiting){Good(b,"save_game",slot:6);var old=JsonUtility.FromJson<CafeSaveEnvelope>(File.ReadAllText(Path.Combine(folder,"slot-6.json")));old.equipment_conversations=null;old.equipment_conversation_selected=null;File.WriteAllText(Path.Combine(folder,"slot-6.json"),JsonUtility.ToJson(old));var fresh=new LocalCafeBackend(folder,b.Simulation.Rules);Good(fresh,"load_game",slot:6);Check(waiting?fresh.EquipmentConversations.Length==1 && fresh.EquipmentConversations[0].progress.branch_id=="introduction":fresh.EquipmentConversations.All(r=>r.day!=1),"legacy invented history");Check(!fresh.EquipmentConversations.Any(r=>r.progress.completed),"legacy marked read");}
  public static int Run(string root){checks=0;Directory.CreateDirectory(root);
   foreach(string choice in new[]{"repair","patch","close"}){
    string folder=Path.Combine(root,choice);var b=new LocalCafeBackend(folder,Rules());Setup(b,true);var row=b.EquipmentConversation;
    Check(row.day==1 && row.event_id==CafeEquipmentDialogue.EventId(1),"case identity");var before=Facts(b);var view=b.View();Check(view.store_event.choices.All(c=>c.can_select),"initial choices unavailable");Check(Facts(b)==before,"preview mutated state");Legacy(b,folder,true);
    row.progress.node=1;row.progress.page_offset=2;Good(b,"save_game",slot:2);var fresh=new LocalCafeBackend(folder,Rules());Good(fresh,"load_game",slot:2);fresh.PrepareEquipmentConversation();Check(fresh.EquipmentConversation.progress.node==1 && fresh.EquipmentConversation.progress.page_offset==2,"intro restart");
    Check(Send(b,"resolve_store_event",choice,id:"wrong").result!=UnityWebRequest.Result.Success && Facts(b)==before,"wrong case accepted");double funds=b.Simulation.State.funds;Good(b,"resolve_store_event",choice);b.PrepareEquipmentConversation();Check(b.EquipmentConversation.day==1 && b.EquipmentResultPending,"result missing");Check(b.Simulation.State.store_events[0].choice==choice,"wrong answer");Check(choice=="close"?b.Simulation.State.day==2 && b.Simulation.State.funds==view.day_off.funds_after:b.Simulation.State.funds==funds,"settlement timing");
    before=Facts(b);Check(Send(b,"resolve_store_event",choice).result!=UnityWebRequest.Result.Success && Facts(b)==before,"double answer");Check(Send(b,"day_off").result!=UnityWebRequest.Result.Success && Facts(b)==before,"hidden result progresses");Check(Send(b,"continue_goal").result!=UnityWebRequest.Result.Success,"goal bypass");
    b.EquipmentConversation.progress.node=1;Good(b,"save_game",slot:3);fresh=new LocalCafeBackend(folder,Rules());Good(fresh,"load_game",slot:3);fresh.PrepareEquipmentConversation();Check(fresh.EquipmentConversation.day==1 && fresh.EquipmentConversation.progress.node==1 && fresh.EquipmentResultPending,"result restart");
    Finish(b);Check(Facts(b)==before && !b.EquipmentResultPending,"reading mutated facts");Check(b.Replays.Load().entries.Any(e=>e.conversation_id==CafeEquipmentDialogue.Id && e.branch_id==choice),"Extra absent");CafeReplayCatalog.Validate(b.Replays.Load());Legacy(b,folder,false);
    if(choice=="close"){b.PrepareEquipmentConversation();Check(b.EquipmentConversation.day==2 && b.EquipmentConversation.progress.branch_id=="introduction","next trouble mixed");Good(b,"resolve_store_event","patch");b.PrepareEquipmentConversation();Check(b.EquipmentConversation.day==2,"second result mixed");Finish(b);Good(b,"save_game",slot:4);CafeReplayCatalog.Validate(b.Replays.Load());}
    else {Good(b,"start_business");int guard=0;while(b.Simulation.State.phase=="open" && guard++<100)Good(b,"advance_business");Check(b.Simulation.State.phase=="closed","closing stuck");Check(b.Simulation.State.expenses==b.Simulation.Rules.base_cost+b.Simulation.Rules.per_seat_cost*b.Simulation.State.seat_count+(choice=="repair"?b.Simulation.Rules.store_events.trouble_cost:0),"repair/base cost differs");}
   }
   var poorRules=Rules();poorRules.starting_funds=1;var poor=new LocalCafeBackend(Path.Combine(root,"poor"),poorRules);Setup(poor);Good(poor,"day_off");Check(poor.EquipmentResultPending && poor.Simulation.State.day==1 && poor.Simulation.State.game_over!=null,"funds ending loses result");Good(poor,"save_game",slot:3);Finish(poor);Check(poor.OutcomePending,"ending absent after result");
   var blocked=new LocalCafeBackend(Path.Combine(root,"blocked"),Rules());Setup(blocked);blocked.Simulation.State.goal.Add(new CafeGoalStage{status="active",started_day=1});blocked.Simulation.State.reservation.status="accepted";blocked.Simulation.State.reservation.choice="accept";blocked.Simulation.State.reservation.offered_day=1;blocked.Simulation.State.reservation.visit_day=1;Check(!blocked.View().store_event.choices[2].can_select && blocked.View().store_event.choices[2].reason.Contains("予約"),"reservation reason absent");beforeBlock=Facts(blocked);Check(Send(blocked,"day_off").result!=UnityWebRequest.Result.Success && Facts(blocked)==beforeBlock,"reservation rest applied");
   var overlapRules=Rules();overlapRules.growth.threshold=(int)overlapRules.growth.rest_xp;
   var overlap=new LocalCafeBackend(Path.Combine(root,"overlap"),overlapRules);Setup(overlap);var missing=overlap.Simulation.State.cats[0];missing.activity="missing";missing.missing_remaining=1;missing.working=false;
   Good(overlap,"day_off");Check(overlap.EquipmentResultPending && overlap.Simulation.GrowthWaiting && overlap.Simulation.State.phase=="closed" && missing.missing_remaining==0,"growth/return overlap lost");
   Check(Send(overlap,"resolve_growth","rest").result!=UnityWebRequest.Result.Success,"growth precedes equipment result");Finish(overlap);Check(!overlap.EquipmentBlocksProgress && overlap.Simulation.GrowthWaiting && overlap.View().missing_cats.Any(c=>c.status=="waiting"),"growth/return lost after reading");
   var other=new LocalCafeBackend(Path.Combine(root,"other-waiting"),Rules());Setup(other);other.Simulation.State.intake_request.status="waiting";var unchanged=Facts(other);Check(!other.View().store_event.choices[2].can_select && other.View().store_event.choices[2].reason.Contains("受け入れ"),"other waiting reason absent");Check(Send(other,"day_off").result!=UnityWebRequest.Result.Success && Facts(other)==unchanged,"other waiting skipped");
   var goalRules=Rules();goalRules.goal_stages[0].days=1;goalRules.goal_stages[0].target=10000;
   var goal=new LocalCafeBackend(Path.Combine(root,"goal"),goalRules);goal.Simulation.Restore(new CafeSimulation(goalRules,Seed(goalRules),"popularity").State);goal.PrepareEquipmentConversation();Good(goal,"day_off");Check(goal.EquipmentResultPending && goal.Simulation.GoalWaiting && goal.OutcomePending,"goal overlap lost");Good(goal,"save_game",slot:3);var goalRestart=new LocalCafeBackend(Path.Combine(root,"goal"),goalRules);Good(goalRestart,"load_game",slot:3);Check(goalRestart.EquipmentResultPending && goalRestart.OutcomePending,"goal overlap restart lost");Finish(goal);Check(goal.OutcomePending && !goal.EquipmentBlocksProgress,"goal result not resumed");
   var auto=new LocalCafeBackend(Path.Combine(root,"autoplay-stop"),Rules());Setup(auto);Good(auto,"resolve_store_event","repair");auto.Simulation.State.autoplay=new CafeAutoRun{running=true,limit=1,run_id="qa",objective="popularity",mode="basic"};double autoFunds=auto.Simulation.State.funds;Good(auto,"pause_autoplay");Good(auto,"stop_autoplay");Check(auto.EquipmentResultPending && auto.Simulation.State.autoplay.running==false && auto.Simulation.State.funds==autoFunds,"result prevents stopping autoplay");
   return checks;
  }
  static string beforeBlock;
  string output;LocalCafeBackend backend;
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"--catcafe-equipment-adv-check");if(i<0)return;var q=new GameObject("Equipment ADV QA").AddComponent<StandaloneEquipmentConversationSmoke>();DontDestroyOnLoad(q);q.output=Path.GetFullPath(a[i+1]);Directory.CreateDirectory(q.output);Application.runInBackground=true;q.StartCoroutine(q.Guard());}
  System.Collections.IEnumerator Guard(){var run=Player();while(true){object next;try{if(!run.MoveNext())yield break;next=run.Current;}catch(Exception ex){File.WriteAllText(Path.Combine(output,"failure.txt"),ex.ToString());throw;}yield return next;}}
  static void Apply(PythonStateClient c)=>typeof(PythonStateClient).GetMethod("Accept",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(c,new object[]{(CafeBackends.Local as LocalCafeBackend).View()});
  System.Collections.IEnumerator Player(){yield return new WaitForSecondsRealtime(1);Run(Path.Combine(output,"backend"));backend=new LocalCafeBackend(Path.Combine(output,"manual"),Rules());bool restart=Environment.GetCommandLineArgs().Contains("--equipment-resume");if(restart)Good(backend,"load_game",slot:9);else Setup(backend,true);CafeBackends.UseLocal(backend);UnityEngine.SceneManagement.SceneManager.LoadScene("CatCafePythonState");yield return new WaitForSecondsRealtime(2);var c=FindObjectOfType<PythonStateClient>();Apply(c);yield return null;var ui=c.GetComponent<EquipmentConversationPanel>();Check(ui!=null && ui.Showing,"UI absent");
   if(!restart){backend.EquipmentConversation.progress.node=3;Apply(c);yield return null;var rest=c.GetComponent<PythonDayOffPanel>();ui.GetComponentsInChildren<UnityEngine.UI.Button>().First(x=>x.GetComponentInChildren<UnityEngine.UI.Text>().text.StartsWith("休業（")).onClick.Invoke();yield return null;Check(rest.panel.activeInHierarchy,"third choice did not open preview");string before=Facts(backend);rest.Choose();yield return null;Check(rest.confirmation.activeInHierarchy,"confirmation absent");rest.Cancel();Check(Facts(backend)==before && backend.Simulation.StoreEventWaiting,"cancel mutated state");rest.Choose();rest.Confirm();rest.Confirm();yield return new WaitForSecondsRealtime(2);Apply(c);yield return null;Check(backend.Simulation.State.day==2 && backend.EquipmentConversation.day==1 && ui.Showing,"overnight UI result absent");ui.Close();c.GetComponent<PythonEventListPanel>().Store();yield return null;Check(ui.Showing,"list resume absent");backend.EquipmentConversation.progress.node=1;backend.EquipmentConversation.progress.page_offset=0;Good(backend,"save_game",slot:9);}
   else Check(backend.EquipmentConversation.day==1 && backend.EquipmentConversation.progress.node==1,"separate restart failed");
   if(!restart){
    foreach(string branch in new[]{"repair","patch","close"})backend.Replays.Merge(new LocalCafeBackend(Path.Combine(output,"backend/"+branch),Rules()).Replays.Load().entries);
    string facts=Facts(backend),meta=JsonUtility.ToJson(backend.EquipmentConversations);UnityEngine.SceneManagement.SceneManager.LoadScene("CatCafeTitle");yield return new WaitForSecondsRealtime(2);var extra=FindObjectOfType<PythonTitleScreen>().GetComponent<TitleExtraPanel>();extra.Open();yield return null;
    foreach(string branch in new[]{"repair","patch","close"}){extra.OpenReplay(CafeEquipmentDialogue.Id+"/"+branch);yield return null;Check(extra.Replay.Showing,"Extra UI absent "+branch);extra.Replay.Answer(true);extra.Replay.Next();extra.Replay.Close();}
    Check(Facts(backend)==facts && JsonUtility.ToJson(backend.EquipmentConversations)==meta,"Extra changed facts/progress");extra.Hide();UnityEngine.SceneManagement.SceneManager.LoadScene("CatCafePythonState");yield return new WaitForSecondsRealtime(2);c=FindObjectOfType<PythonStateClient>();Apply(c);yield return null;
   }
   Screen.SetResolution(restart?1024:1280,restart?768:800,false);Apply(c);File.WriteAllText(Path.Combine(output,restart?"restart-result.txt":"result.txt"),"PASS: "+checks);ScreenCapture.CaptureScreenshot(Path.Combine(output,restart?"restart.png":"manual-ready.png"));
  }
 }
}
